# Generated by `cargo xtask formula` in https://github.com/michel-onstein/acs for each release
# (scripts/update-tap.sh): edit the generator there, not this file.
# acs-version: 0.20.0
#
# acs releases are signed; SHA256SUMS.sig is checked against this key:
#   ssh-ed25519 AAAAC3NzaC1lZDI1NTE5AAAAILbxQW5C9X7CdwcQ4bab0gsQi4Evk2xfgmI/972dlHCb acs release signing
# Verify a release by hand:
#   printf 'releases@acs namespaces="acs-release" %s\n' "$key" > allowed
#   ssh-keygen -Y verify -f allowed -I releases@acs -n acs-release -s SHA256SUMS.sig < SHA256SUMS
class Acs < Formula
  desc "Persistent, reconnecting remote shells over ssh"
  homepage "https://github.com/michel-onstein/acs"
  license "MIT"

  livecheck do
    url :stable
    strategy :github_latest
  end

  on_macos do
    on_arm do
      url "https://github.com/michel-onstein/acs/releases/download/0.20.0/acs-0.20.0-aarch64-apple-darwin.tar.gz"
      sha256 "452e062bde1a90bf4ec4a3b95e1a452ae05a167b13ddff2db59dd09b1daf10ee"
    end

    on_intel do
      url "https://github.com/michel-onstein/acs/releases/download/0.20.0/acs-0.20.0-x86_64-apple-darwin.tar.gz"
      sha256 "6ddcf273459adec56ee7a12a194591a2086b1e6219d3d9f4982513657e821080"
    end
  end

  on_linux do
    on_arm do
      url "https://github.com/michel-onstein/acs/releases/download/0.20.0/acs-0.20.0-aarch64-unknown-linux-musl.tar.gz"
      sha256 "c1d87835a287021d694d0d93d6f919d1c557c244e379838320f7e7f8e9182fa0"
    end

    on_intel do
      url "https://github.com/michel-onstein/acs/releases/download/0.20.0/acs-0.20.0-x86_64-unknown-linux-musl.tar.gz"
      sha256 "012d578aec587b958e8fe0fcaa6a2aff8f60657eee09364ed5f0771a7e939f45"
    end
  end

  def install
    bin.install "acs"
    bin.install_symlink "acs" => "acscp"
  end

  test do
    out = shell_output("#{bin}/acs --version")
    assert_match "acs #{version} ", out
    remotes = out[/^installs remotes: (.*)$/, 1].to_s.split(", ")
    assert_includes remotes, "x86_64-unknown-linux-musl"
    assert_includes remotes, "aarch64-unknown-linux-musl"
    assert_match "acs #{version} ", shell_output("#{bin}/acscp --version")
  end
end
